
(function(){
  'use strict';
  const NEW_AGENT='Paola Brum';
  const targetNames=new Set([
    'Creche Municipal Mané Garrincha I',
    'Creche Municipal Sempre Vida Palmeirinha',
    'Espaço de Desenvolvimento Infantil Professor Ubirajara de Paula Castro',
    'Creche Municipal Manoel da Rocha Aprisco',
    'Escola Municipal Oswaldo Goeldi',
    'Escola Municipal Rostham Pedro de Farias',
    'Escola Municipal Cervantes',
    'Escola Municipal Francisco Palheta',
    'Escola Municipal Ruy Carneiro da Cunha',
    'Escola Municipal Padre Dehon',
    'Escola Municipal Barão de Itararé',
    'Escola Municipal Silvio Romero'
  ]);
  const normLocal=value=>{
    try{return typeof norm==='function'?norm(value):String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();}
    catch(_){return String(value||'').toLowerCase().trim();}
  };
  const targetNorm=new Set([...targetNames].map(normLocal));
  const matchesName=value=>targetNorm.has(normLocal(value));

  function patchStructuralRecords(){
    let changed=0;
    const pools=[];
    try{if(typeof ALL_STRUCTURAL_RECORDS!=='undefined'&&Array.isArray(ALL_STRUCTURAL_RECORDS))pools.push(ALL_STRUCTURAL_RECORDS);}catch(_){}
    try{if(typeof DATA!=='undefined'&&Array.isArray(DATA.records))pools.push(DATA.records);}catch(_){}
    try{if(typeof STRUCTURAL_COMPLEMENT_RECORDS!=='undefined'&&Array.isArray(STRUCTURAL_COMPLEMENT_RECORDS))pools.push(STRUCTURAL_COMPLEMENT_RECORDS);}catch(_){}
    const seen=new Set();
    pools.forEach(pool=>pool.forEach(record=>{
      if(!record||seen.has(record))return;seen.add(record);
      if(Number(record.cre)===5&&matchesName(record.unidade)){record.agente=NEW_AGENT;changed++;}
    }));
    return changed;
  }
  function patchGeoPoints(){
    let changed=0;
    try{
      (GEO_POINTS||[]).forEach(point=>{
        if(Number(point.cre)===5&&matchesName(point.name)){point.agent=NEW_AGENT;changed++;}
      });
    }catch(_){}
    return changed;
  }
  function patchResultRows(){
    const patchRows=rows=>{
      if(!Array.isArray(rows))return 0;
      let changed=0;
      rows.forEach(row=>{
        const cre=typeof creNumber==='function'?creNumber(row?.cre||row?.regional||''):Number(String(row?.cre||row?.regional||'').match(/\d+/)?.[0]||0);
        if(cre!==5)return;
        let record=null;
        try{record=typeof somFindRecord==='function'?somFindRecord(row?.escola||''):null;}catch(_){}
        if((record&&matchesName(record.unidade))||matchesName(row?.escola)){row.agente=NEW_AGENT;changed++;}
      });
      return changed;
    };
    let total=0;
    try{total+=patchRows(SOM_ROWS);}catch(_){}
    try{total+=patchRows(SOM_INITIAL);}catch(_){}
    const adrReady=window.__GRA_SECTION_INIT?.adrs===true||document.getElementById('adrs')?.classList.contains('active');
    if(adrReady){
      try{total+=patchRows(ADR_ROWS);}catch(_){}
      try{total+=patchRows(ADR_INITIAL);}catch(_){}
    }
    return total;
  }
  window.__graV204PatchResultRows=patchResultRows;
  function applyPhoto(){
    try{
      if(typeof GEO_AGENT_PHOTOS!=='undefined')GEO_AGENT_PHOTOS[NEW_AGENT]='data:image/png;base64,';
      if(typeof GEO_AGENT_PHOTO_POS!=='undefined')GEO_AGENT_PHOTO_POS[NEW_AGENT]='50% 36%';
    }catch(_){}
  }
  function refreshUI(){
    try{
      const scope=document.getElementById('regionalScopeSelect')?.value||'';
      if(typeof applyStructuralScope==='function')applyStructuralScope(scope);
    }catch(e){console.warn('v204 structural refresh',e);}
    try{if(typeof SCHOOL_LOOKUP_CACHE!=='undefined')SCHOOL_LOOKUP_CACHE=null;}catch(_){}
    try{if(typeof somRefreshSelectors==='function')somRefreshSelectors();}catch(_){}
    try{if(typeof adrRefreshSelectors==='function')adrRefreshSelectors();}catch(_){}
    try{if(typeof populateGeoAgents==='function')populateGeoAgents();}catch(_){}
    try{if(typeof renderResultados==='function')renderResultados();}catch(_){}
    try{if(typeof renderADRs==='function')renderADRs();}catch(_){}
    try{if(typeof geoRender==='function')geoRender();}catch(_){}
    try{if(typeof geo3dUpdatePoints==='function'&&typeof geoVisiblePoints==='function')geo3dUpdatePoints(geoVisiblePoints());}catch(_){}
  }
  function applyAll(){
    patchStructuralRecords();
    applyPhoto();
    try{if(typeof SCHOOL_LOOKUP_CACHE!=='undefined')SCHOOL_LOOKUP_CACHE=null;}catch(_){}
    patchResultRows();
    patchGeoPoints();
    refreshUI();
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(applyAll,120),{once:true});
  else setTimeout(applyAll,120);
  // Reaplica após a restauração assíncrona das bases locais, se houver.
  setTimeout(applyAll,900);
  setTimeout(applyAll,2200);
})();
